  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The Higgs boson discovery confirmed a central prediction of the Standard Model and completed its particle inventory. It is a landmark result in experimental physics.",
        "attribution": "ATLAS and CMS made independent discoveries through enormous collaborations. These three leaders are credible representatives of the conception and construction of the experiments, though credit across the collaborations is necessarily broader.",
        "maturity": "The discovery has been repeatedly confirmed, and the particle's properties have been studied for more than a decade.",
        "uncertainties": [
          "The laureate limit cannot represent the thousands whose work was essential to the experiments."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrinos as a new observational channel on the universe, opening a field of astroparticle physics with lasting scientific reach.",
        "attribution": "Halzen's leadership and role in developing the detector and field make him a strong individual choice; the discovery and its follow-up depend on the international IceCube collaboration.",
        "maturity": "The detector has produced a sustained body of results, including evidence for astrophysical sources, rather than a single transient claim.",
        "uncertainties": [
          "Source identification remains incomplete, and attribution within a large detector collaboration requires careful review."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the microwave background transformed cosmology into a quantitative field and established key parameters of the standard model.",
        "attribution": "Bennett and Page represent the instrument and experimental leadership; Spergel's analysis and interpretation helped establish the cosmological implications. The mission's wider team also deserves substantial credit.",
        "maturity": "The measurements have been extensively checked against later observations, including Planck, and their central conclusions remain foundational.",
        "uncertainties": [
          "The exact balance of credit among mission leadership, instrument builders, and the broad analysis team merits scrutiny."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have brought atomic timekeeping to extraordinary precision and created a new platform for tests of fundamental physics and precision sensing.",
        "attribution": "Katori and Ye independently led complementary approaches that established the field, making shared recognition appropriate.",
        "maturity": "The precision has been demonstrated and improved over many years, with clocks now enabling reproducible comparisons and applications beyond timekeeping.",
        "uncertainties": [
          "The prize case may depend on whether the defining achievement is the clock concept, its realization, or the later precision record."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "Shaun Cole",
        "Will J. Percival"
      ],
      "assessment": {
        "nobel_worthiness": "Using baryon acoustic oscillations as a standard ruler supplied a robust way to measure cosmic expansion and helped make precision cosmology possible.",
        "attribution": "These leaders are closely associated with the surveys and analyses that established the method observationally; recognition should reflect the substantial work of the survey collaborations.",
        "maturity": "BAO measurements have been replicated by successive surveys and remain central to current cosmological constraints.",
        "uncertainties": [
          "The discovery and its development span several surveys, so the most decisive contributions need to be distinguished."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "Identifying gamma-ray burst afterglows established their cosmological distances and changed the understanding of these powerful transients.",
        "attribution": "Costa and Frontera's BeppoSAX work enabled the rapid localizations; Kulkarni and collaborators made pivotal optical follow-up observations. These contributions form a coherent discovery chain.",
        "maturity": "The cosmological origin and transient nature of gamma-ray bursts have been established through extensive observations and a mature theoretical framework.",
        "uncertainties": [
          "The work involved multiple missions and follow-up teams, and the boundary between discovery and subsequent characterization is not sharp."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Christophe Salomon",
        "John E. Thomas",
        "Rudolf Grimm"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases gave controlled access to a fundamental many-body regime and made the BEC-BCS crossover and fermionic superfluidity experimentally accessible.",
        "attribution": "These experimentalists led complementary platforms and landmark measurements; credit should be apportioned according to the specific realizations that established the field.",
        "maturity": "The crossover has been explored in depth over many years and is now a standard tool for studying strongly correlated quantum matter.",
        "uncertainties": [
          "Several groups made important early and subsequent contributions, so selection of a small laureate group needs a clear discovery criterion."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "A nanohertz gravitational-wave background would open a new frequency band in gravitational-wave astronomy and probe populations of massive black holes across cosmic history.",
        "attribution": "The named pulsar-timing researchers made major contributions to the long-term observations and analyses; the evidence is the product of international timing collaborations.",
        "maturity": "Multiple pulsar timing arrays report evidence for a common low-frequency signal, but the field is still establishing the background interpretation and its sources.",
        "uncertainties": [
          "The signal's astrophysical origin and the strength of its distinction from correlated noise remain unsettled.",
          "Independent confirmation and continued characterization are needed before treating this as a mature discovery."
        ]
      }
    }
  ]
}
